import re,os,sys
roots=['scripts','tools','.claude','workplan/pipeline-state-graph','.github']
pat=re.compile(r'\b(base_parameters|evidence_sources)\b')
life={'base_parameters':re.compile(r"\bstatus\b"),'evidence_sources':re.compile(r"superseded_by_ref_id")}
out=[]
for root in roots:
    for dp,dn,fn in os.walk(root):
        if '__pycache__' in dp or 'migrations' in dp: continue
        for f in fn:
            if not f.endswith('.py'): continue
            p=os.path.join(dp,f)
            try: lines=open(p,encoding='utf-8').read().split('\n')
            except: continue
            for i,l in enumerate(lines):
                if not re.search(r'\b(FROM|JOIN)\s+"?(base_parameters|evidence_sources)"?\b',l,re.I): continue
                t='base_parameters' if 'base_parameters' in l else 'evidence_sources'
